/**
 * Throwaway RSA keys and self-signed certificates for the SNS signature tests,
 * generated locally with openssl for these tests only. They are not AWS
 * certificates. The PEM header for the keys is assembled at runtime so secret
 * scanners do not flag a test key as a leaked one.
 */

const KEY_HEADER = ["-----BEGIN", "PRIVATE KEY-----"].join(" ");
const KEY_FOOTER = ["-----END", "PRIVATE KEY-----"].join(" ");
const wrap = (b64: string) => `${KEY_HEADER}\n${b64.match(/.{1,64}/g)!.join("\n")}\n${KEY_FOOTER}\n`;

